"""
Regression test for: frozen attrs exception classes should allow their
``__traceback__`` attribute to be set/reassigned, since that's part of
normal exception machinery (context managers, re-raising, etc.) and not
user code mutating frozen fields.

See: https://github.com/python-attrs/attrs frozen exception + traceback bug.
"""

from contextlib import contextmanager

import attrs


def test_frozen_exception_traceback_can_be_reassigned():
    @attrs.frozen
    class MyException(Exception):
        pass

    try:
        raise MyException()
    except MyException as e:
        # This must NOT raise FrozenInstanceError -- setting __traceback__
        # is normal exception machinery, not user code touching frozen
        # fields.
        e.__traceback__ = e.__traceback__


def test_frozen_exception_with_context_manager():
    @attrs.frozen
    class MyException(Exception):
        pass

    @contextmanager
    def do_nothing():
        yield

    with_exception_raised = False
    try:
        with do_nothing():
            raise MyException()
    except MyException:
        with_exception_raised = True

    assert with_exception_raised

